// Generates the artwork of the "42 - ouroboros" NFT.
//
//   node mint/scripts/generateArt.js
//
// Output:
//   mint/assets/42-ouroboros.svg   (vector master, uploaded to IPFS)
//   mint/assets/42-ouroboros.png   (2000x2000 raster export for wallets that
//                                   do not render SVG)
//
// The image is generated by code (no external assets, no fonts) so that it is
// fully reproducible: the "42" is drawn with vector paths, so it renders the
// same way in every browser / wallet / explorer.

const fs = require("fs");
const path = require("path");
const { Resvg } = require("@resvg/resvg-js");

const ASSETS_DIR = path.join(__dirname, "..", "assets");
const SVG_OUTPUT = path.join(ASSETS_DIR, "42-ouroboros.svg");
const PNG_OUTPUT = path.join(ASSETS_DIR, "42-ouroboros.png");

// ---------------------------------------------------------------------------
// Geometry helpers
// ---------------------------------------------------------------------------

const CANVAS_SIZE = 1000;
const CENTER = CANVAS_SIZE / 2;
const SNAKE_RADIUS = 310; // radius of the snake's centre line

/**
 * Converts polar coordinates to canvas coordinates.
 * Angle is in degrees, 0 = top of the circle, increasing clockwise.
 */
function polarToPoint(angleDeg, radius) {
  const angleRad = (angleDeg * Math.PI) / 180;
  return [CENTER + radius * Math.sin(angleRad), CENTER - radius * Math.cos(angleRad)];
}

const formatPoint = ([x, y]) => `${x.toFixed(2)} ${y.toFixed(2)}`;

// The snake's body runs clockwise from the tail tip (angle 12°) all the way
// around the circle to the tip of its snout (angle 382° = 22°), so the snout
// ends up swallowing the tail.
const TAIL_TIP_ANGLE = 12;
const NECK_START_ANGLE = 330;
const HEAD_START_ANGLE = 346;
const SNOUT_TIP_ANGLE = 382;

const BODY_WIDTH = 62;
const NECK_WIDTH = 54;
const HEAD_MAX_WIDTH = 98;

/** Thickness of the snake at a given angle along its body. */
function snakeWidthAt(angle) {
  if (angle <= 130) {
    // Tail: grows from a thin tip to the full body width.
    const progress = (angle - TAIL_TIP_ANGLE) / (130 - TAIL_TIP_ANGLE);
    return 4 + (BODY_WIDTH - 4) * Math.pow(Math.max(progress, 0), 0.7);
  }
  if (angle <= NECK_START_ANGLE) {
    // Body: constant width with a very subtle "breathing" swell.
    return BODY_WIDTH + 3 * Math.sin(((angle - 130) / 200) * Math.PI);
  }
  if (angle <= HEAD_START_ANGLE) {
    // Neck: slightly thinner than the body.
    const progress = (angle - NECK_START_ANGLE) / (HEAD_START_ANGLE - NECK_START_ANGLE);
    return BODY_WIDTH + (NECK_WIDTH - BODY_WIDTH) * progress;
  }
  // Head: widens behind the eyes, then rounds off into the snout.
  const progress = (angle - HEAD_START_ANGLE) / (SNOUT_TIP_ANGLE - HEAD_START_ANGLE);
  const widestPoint = 0.55;
  if (progress <= widestPoint) {
    const t = progress / widestPoint;
    const smoothStep = t * t * (3 - 2 * t); // flat at both ends -> no visible corner
    return NECK_WIDTH + (HEAD_MAX_WIDTH - NECK_WIDTH) * smoothStep;
  }
  const snoutProgress = (progress - widestPoint) / (1 - widestPoint);
  return HEAD_MAX_WIDTH * Math.sqrt(Math.max(1 - snoutProgress * snoutProgress, 0));
}

/** Closed outline (SVG path) of the snake between two angles. */
function snakeOutlinePath(fromAngle, toAngle, step = 0.5) {
  const outerEdge = [];
  const innerEdge = [];
  for (let angle = fromAngle; angle <= toAngle + 1e-9; angle += step) {
    const halfWidth = snakeWidthAt(angle) / 2;
    outerEdge.push(polarToPoint(angle, SNAKE_RADIUS + halfWidth));
    innerEdge.push(polarToPoint(angle, SNAKE_RADIUS - halfWidth));
  }
  const points = [...outerEdge, ...innerEdge.reverse()];
  return `M ${points.map(formatPoint).join(" L ")} Z`;
}

/**
 * Only the two side edges (outer + inner) of a body section, as open lines.
 * Used to outline overlay pieces without drawing a seam across the body.
 */
function snakeEdgesPath(fromAngle, toAngle, step = 0.5) {
  const outerEdge = [];
  const innerEdge = [];
  for (let angle = fromAngle; angle <= toAngle + 1e-9; angle += step) {
    const halfWidth = snakeWidthAt(angle) / 2;
    outerEdge.push(polarToPoint(angle, SNAKE_RADIUS + halfWidth));
    innerEdge.push(polarToPoint(angle, SNAKE_RADIUS - halfWidth));
  }
  return `M ${outerEdge.map(formatPoint).join(" L ")} M ${innerEdge.map(formatPoint).join(" L ")}`;
}

/** Chevron-shaped scales along the body, pointing towards the head. */
function scalesPath() {
  const chevrons = [];
  for (let angle = 30; angle <= 322; angle += 5.5) {
    const halfWidth = (snakeWidthAt(angle) / 2) * 0.85;
    const upper = polarToPoint(angle - 3.2, SNAKE_RADIUS + halfWidth);
    const middle = polarToPoint(angle, SNAKE_RADIUS);
    const lower = polarToPoint(angle - 3.2, SNAKE_RADIUS - halfWidth);
    chevrons.push(`M ${formatPoint(upper)} L ${formatPoint(middle)} L ${formatPoint(lower)}`);
  }
  return chevrons.join(" ");
}

/** Open jaws at the snout, where the tail disappears. */
function mouthPath() {
  const snoutTip = polarToPoint(SNOUT_TIP_ANGLE + 0.6, SNAKE_RADIUS);
  const upperJaw = polarToPoint(SNOUT_TIP_ANGLE - 3.5, SNAKE_RADIUS + 26);
  const mouthCorner = polarToPoint(SNOUT_TIP_ANGLE - 15, SNAKE_RADIUS + 2);
  const lowerJaw = polarToPoint(SNOUT_TIP_ANGLE - 3.5, SNAKE_RADIUS - 26);
  return `M ${formatPoint(snoutTip)} L ${formatPoint(upperJaw)} L ${formatPoint(mouthCorner)} L ${formatPoint(lowerJaw)} Z`;
}

/** Deterministic pseudo-random generator so the starfield never changes. */
function createSeededRandom(seed) {
  let state = seed;
  return () => {
    state = (state * 1664525 + 1013904223) % 4294967296;
    return state / 4294967296;
  };
}

function starfield() {
  const random = createSeededRandom(42);
  const stars = [];
  while (stars.length < 90) {
    const x = random() * CANVAS_SIZE;
    const y = random() * CANVAS_SIZE;
    const distanceFromCenter = Math.hypot(x - CENTER, y - CENTER);
    // Keep stars away from the snake ring so the composition stays clean.
    if (Math.abs(distanceFromCenter - SNAKE_RADIUS) < 80) continue;
    const radius = (0.6 + random() * 1.6).toFixed(2);
    const opacity = (0.25 + random() * 0.6).toFixed(2);
    stars.push(`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${radius}" opacity="${opacity}"/>`);
  }
  return stars.join("");
}

// ---------------------------------------------------------------------------
// SVG composition
// ---------------------------------------------------------------------------

function buildSvg() {
  const fullBody = snakeOutlinePath(TAIL_TIP_ANGLE, SNOUT_TIP_ANGLE);
  const head = snakeOutlinePath(NECK_START_ANGLE, SNOUT_TIP_ANGLE);
  const tailTip = snakeOutlinePath(TAIL_TIP_ANGLE, TAIL_TIP_ANGLE + 14);
  const [eyeX, eyeY] = polarToPoint(362, SNAKE_RADIUS + 20);

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${CANVAS_SIZE} ${CANVAS_SIZE}" width="${CANVAS_SIZE}" height="${CANVAS_SIZE}">
  <title>42 - ouroboros</title>
  <desc>A golden ouroboros, the serpent eating its own tail, encircling the number 42. Artist: abasante.</desc>
  <defs>
    <radialGradient id="background" cx="50%" cy="50%" r="70%">
      <stop offset="0" stop-color="#1c2346"/>
      <stop offset="0.6" stop-color="#0c1024"/>
      <stop offset="1" stop-color="#05060d"/>
    </radialGradient>
    <linearGradient id="scalesGold" gradientUnits="userSpaceOnUse" x1="170" y1="170" x2="830" y2="830">
      <stop offset="0" stop-color="#fbe39a"/>
      <stop offset="0.45" stop-color="#d9a43a"/>
      <stop offset="1" stop-color="#8f5c14"/>
    </linearGradient>
    <linearGradient id="digitsFill" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#fffaf0"/>
      <stop offset="1" stop-color="#f3cf7a"/>
    </linearGradient>
    <filter id="softGlow" x="-50%" y="-50%" width="200%" height="200%">
      <feGaussianBlur stdDeviation="18"/>
    </filter>
    <clipPath id="bodyClip"><path d="${fullBody}"/></clipPath>
  </defs>

  <!-- Night sky -->
  <rect width="${CANVAS_SIZE}" height="${CANVAS_SIZE}" fill="url(#background)"/>
  <g fill="#f6ecd2">${starfield()}</g>

  <!-- Faint guide rings -->
  <g fill="none" stroke="#d9a43a">
    <circle cx="${CENTER}" cy="${CENTER}" r="${SNAKE_RADIUS + 75}" stroke-width="1" opacity="0.18"/>
    <circle cx="${CENTER}" cy="${CENTER}" r="${SNAKE_RADIUS - 70}" stroke-width="1" opacity="0.18"/>
    <circle cx="${CENTER}" cy="${CENTER}" r="${SNAKE_RADIUS}" stroke-width="110" opacity="0.10" filter="url(#softGlow)"/>
  </g>

  <!-- The serpent -->
  <path d="${fullBody}" fill="url(#scalesGold)" stroke="#4a2e06" stroke-width="3" stroke-linejoin="round"/>
  <path d="${scalesPath()}" clip-path="url(#bodyClip)" fill="none" stroke="#6b430b" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.55"/>
  <path d="${head}" fill="url(#scalesGold)"/>
  <path d="${snakeEdgesPath(NECK_START_ANGLE, SNOUT_TIP_ANGLE)}" fill="none" stroke="#4a2e06" stroke-width="3" stroke-linejoin="round"/>
  <path d="${mouthPath()}" fill="#0c1024" stroke="#4a2e06" stroke-width="2.5" stroke-linejoin="round"/>
  <path d="${tailTip}" fill="url(#scalesGold)"/>
  <path d="${snakeEdgesPath(TAIL_TIP_ANGLE, TAIL_TIP_ANGLE + 14)}" fill="none" stroke="#4a2e06" stroke-width="2" stroke-linejoin="round"/>
  <circle cx="${eyeX.toFixed(2)}" cy="${eyeY.toFixed(2)}" r="8" fill="#0c1024"/>
  <circle cx="${(eyeX - 2.5).toFixed(2)}" cy="${(eyeY - 2.5).toFixed(2)}" r="2.6" fill="#fff6dc"/>

  <!-- 42, drawn as vector strokes (no font dependency) -->
  <g transform="translate(-11 0)" fill="none" stroke-linecap="round" stroke-linejoin="round">
    <g stroke="#f3cf7a" stroke-width="64" opacity="0.35" filter="url(#softGlow)">
      <path d="M 450 630 L 450 370 L 340 540 L 500 540"/>
      <path d="M 533 440 C 533 390 570 370 605 370 C 645 370 677 398 677 437 C 677 470 655 492 630 515 L 533 630 L 682 630"/>
    </g>
    <g stroke="url(#digitsFill)" stroke-width="44">
      <path d="M 450 630 L 450 370 L 340 540 L 500 540"/>
      <path d="M 533 440 C 533 390 570 370 605 370 C 645 370 677 398 677 437 C 677 470 655 492 630 515 L 533 630 L 682 630"/>
    </g>
  </g>
</svg>
`;
}

function main() {
  fs.mkdirSync(ASSETS_DIR, { recursive: true });

  const svg = buildSvg();
  fs.writeFileSync(SVG_OUTPUT, svg);

  const png = new Resvg(svg, { fitTo: { mode: "width", value: 2000 } }).render().asPng();
  fs.writeFileSync(PNG_OUTPUT, png);

  console.log(`SVG written to ${path.relative(process.cwd(), SVG_OUTPUT)} (${svg.length} bytes)`);
  console.log(`PNG written to ${path.relative(process.cwd(), PNG_OUTPUT)} (${png.length} bytes)`);
}

main();
